<?php

namespace LaraGram\Citadel\Database\Factories;

use LaraGram\Citadel\Citadel;
use LaraGram\Database\Eloquent\Factories\Factory;
use LaraGram\Support\Str;

/**
 * @extends \LaraGram\Database\Eloquent\Factories\Factory<\LaraGram\Citadel\Client>
 */
class ClientFactory extends Factory
{
    /**
     * Get the name of the model that is generated by the factory.
     */
    public function modelName(): string
    {
        return $this->model ?? Citadel::clientModel();
    }

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'owner_id' => null,
            'owner_type' => null,
            'name' => 'Client '.Str::random(6),
            'secret' => Str::random(40),
            'redirect_uris' => ['http://localhost/callback'],
            'grant_types' => ['authorization_code', 'refresh_token'],
            'revoked' => false,
        ];
    }

    /**
     * Use as a public client.
     */
    public function asPublic(): static
    {
        return $this->state([
            'secret' => null,
        ]);
    }

    /**
     * Use as a password client.
     */
    public function asPasswordClient(): static
    {
        return $this->state([
            'grant_types' => ['password', 'refresh_token'],
            'redirect_uris' => [],
        ]);
    }

    /**
     * Use as an implicit client.
     */
    public function asImplicitClient(): static
    {
        return $this->state([
            'grant_types' => ['implicit'],
            'secret' => null,
        ]);
    }

    /**
     * Use as a client credentials client.
     */
    public function asClientCredentials(): static
    {
        return $this->state([
            'grant_types' => ['client_credentials'],
            'redirect_uris' => [],
        ]);
    }

    /**
     * Use as a device code client.
     */
    public function asDeviceCodeClient(): static
    {
        return $this->state([
            'grant_types' => ['urn:ietf:params:oauth:grant-type:device_code', 'refresh_token'],
            'redirect_uris' => [],
        ]);
    }

    /**
     * Use as a Telegram (Mini App / Login Widget) client.
     */
    public function asTelegramClient(): static
    {
        return $this->state([
            'grant_types' => ['telegram_init_data', 'telegram_login', 'refresh_token'],
            'redirect_uris' => [],
            'secret' => null,
        ]);
    }
}
